  "The translation appears here": "La traduzione compare qui",
  "Every part is checked: numbers, names and codes kept exactly.": "Ogni parte viene controllata: numeri, nomi e codici restano identici.",
  "Open a PDF, Word file, book or web page. Read it here and chat with it — every answer shows the page it came from. Everything stays on your phone.": "Apri un PDF, un file Word, un libro o una pagina web. Leggilo qui e chatta con lui: ogni risposta mostra la pagina da cui viene. Tutto resta sul tuo telefono.",
  "Open a file": "Apri un file",
  "Reading and searching work now. To chat with the file, install a model in Engine.": "Lettura e ricerca funzionano già. Per chattare con il file, installa un modello in Motore.",
  "Your documents appear here": "I tuoi documenti compaiono qui",
  "Open a file: it is kept on this device, with its chat and notes, so you can come back to it.": "Apri un file: resta su questo dispositivo, con la sua chat e le sue note, così puoi tornarci.",
  "Stop": "Ferma",
  "Describe it in one sentence — the AI on your phone writes a designed PowerPoint or a full report, from the web or your own file. Edit any slide, then save it as PowerPoint, Word or PDF.": "Descrivilo in una frase: l'IA del tuo telefono scrive un PowerPoint impaginato o un report completo, dal web o da un tuo file. Modifica qualsiasi slide, poi salva in PowerPoint, Word o PDF.",
  "Presentation": "Presentazione",
  "Report": "Report",
  "e.g. A pitch for our café to offices in New Cairo: menu, catering, prices, why us": "es. Una presentazione del nostro caffè agli uffici di New Cairo: menù, catering, prezzi, perché noi",
  "Research the web for facts and figures": "Cerca dati e cifre sul web",
  "Each slide names its sources, and a Sources slide lists every page": "Ogni slide cita le sue fonti, e una slide Fonti elenca ogni pagina",
  "Base it on my file (Word, PDF, Excel, CSV…)": "Basati sul mio file (Word, PDF, Excel, CSV…)",
  "Make the presentation": "Crea la presentazione",
  "{n} slides": "{n} slide",
  "Midnight": "Mezzanotte",
  "Short points": "Punti brevi",
  "Change": "Cambia",
  "Your slides appear here": "Le tue slide compaiono qui",
  "Each slide or section shows here as it is written.": "Ogni slide o sezione compare qui mentre viene scritta.",
  "Build a CV in English or Arabic, keep a copy for every job, and export a clean PDF or Word file. The AI on your phone helps with wording.": "Crea un CV in inglese o in arabo, tieni una copia per ogni lavoro ed esporta un PDF o un Word pulito. L'IA del tuo telefono ti aiuta con le parole.",
  "New CV": "Nuovo CV",
  "Import my CV": "Importa il mio CV",
  "No CVs yet": "Ancora nessun CV",
  "Start a new one, or import the one you already have.": "Creane uno nuovo o importa quello che hai già.",
  "Copy a video's link, paste it here, pick the quality — it's saved to your phone's Movies folder. Works with direct video links, Google Drive, Dropbox, archive.org, Wikimedia Commons and pages that show a plain video.": "Copia il link di un video, incollalo qui, scegli la qualità: viene salvato nella cartella Film del telefono. Funziona con link video diretti, Google Drive, Dropbox, archive.org, Wikimedia Commons e pagine che mostrano un semplice video.",
  "Find the video": "Trova il video",
  "The video's versions appear here": "Le versioni del video compaiono qui",
  "Paste a link and tap Find the video — then pick the quality to download.": "Incolla un link e tocca Trova il video, poi scegli la qualità da scaricare.",
  "No map on this device yet": "Ancora nessuna mappa su questo dispositivo",
  "Download the world map to see every country, or your country's map for streets, places and offline search.": "Scarica la mappa del mondo per vedere tutti i paesi, o la mappa del tuo paese per strade, luoghi e ricerca offline.",
