  "= instant filler removal (offline).": "= rimozione istantanea delle parole inutili (offline).",
  "= the model rewrites it far shorter while keeping the meaning.": "= il modello lo riscrive molto più corto mantenendo il senso.",
  "Result": "Risultato",
  "Paste a wordy prompt and hit": "Incolla un prompt prolisso e tocca",
  "— it thinks about meaning, not just filler words.": "— ragiona sul senso, non solo sulle parole inutili.",
  "Text to rewrite": "Testo da riscrivere",
  "Paste AI-generated or stiff text — it comes back sounding like a person wrote it.": "Incolla un testo generato dall'IA o rigido: torna come se l'avesse scritto una persona.",
  "Your writing sample": "Il tuo esempio di scrittura",
  "(this is what makes it sound like you)": "(è questo che lo fa suonare come te)",
  "Paste a few paragraphs you wrote yourself — an email, a message, anything in your natural voice.": "Incolla qualche paragrafo scritto da te: un'email, un messaggio, qualsiasi cosa con la tua voce naturale.",
  "Keeps your meaning and facts exactly — changes only how it reads. The writing sample is optional but makes the biggest difference.": "Mantiene esattamente il tuo senso e i fatti: cambia solo come si legge. L'esempio di scrittura è facoltativo, ma fa la differenza più grande.",
  "Rewritten": "Riscritto",
  "Paste stiff or AI-sounding text, add a sample of your own writing, and it comes back in your voice — same meaning, human rhythm.": "Incolla un testo rigido o che sa di IA, aggiungi un esempio della tua scrittura e torna con la tua voce: stesso senso, ritmo umano.",
  "Chat through Attune — it reads the whole conversation and sharpens every next prompt.": "Chatta tramite Attune: legge tutta la conversazione e rende più preciso ogni prompt successivo.",
  "What do you want out of this whole conversation? (optional, but it makes every prompt better)": "Cosa vuoi ottenere da tutta questa conversazione? (facoltativo, ma migliora ogni prompt)",
  "Bring the chat from {t} — paste the whole conversation or just its last reply:": "Porta la chat da {t}: incolla tutta la conversazione o solo l'ultima risposta:",
  "Paste here…": "Incolla qui…",
  "Read it & suggest my reply": "Leggila e suggerisci la mia risposta",
  "What do you want to ask? Type it however you like.": "Cosa vuoi chiedere? Scrivilo come preferisci.",
  "Optimize my prompt": "Ottimizza il mio prompt",
  "The loop: type intent → get an optimized prompt → send it → bring the reply back → each next prompt is sharper. In the phone app, the share-sheet replaces copy-paste entirely.": "Il ciclo: scrivi l'intenzione → ricevi un prompt ottimizzato → invialo → riporta la risposta → ogni prompt successivo è più preciso. Nell'app, il menu Condividi sostituisce del tutto il copia-incolla.",
  "Ready prompt recipes — pick one, fill the blanks, then": "Ricette di prompt pronte: scegline una, compila gli spazi, poi",
  "to tailor it.": "per adattarla.",
  "· check updates": "· controlla aggiornamenti",
