  "Structure-to-prose is a well-suited LLM task": "Passare da una struttura a un testo è un compito adatto agli LLM",
  "Recipes ship with the app and work offline.": "Le ricette sono incluse nell'app e funzionano offline.",
  "Ask it anything.": "Chiedigli qualsiasi cosa.",
  "It answers from this device, and it can look through everything you've asked it before — so questions about your own work have real answers, not guesses.": "Risponde da questo dispositivo e può consultare tutto ciò che gli hai già chiesto: così le domande sul tuo lavoro hanno risposte vere, non supposizioni.",
