  "Core at full precision: the fastest at reading long messages and files on a 12 GB+ phone, and the most exact answers of the 4B.": "Core a piena precisione: il più veloce a leggere messaggi e file lunghi su un telefono da 12 GB in su, e le risposte più esatte del 4B.",
  "Core made 10% smaller, for a 6 GB phone that is short on free memory.": "Core più piccolo del 10%, per un telefono da 6 GB con poca memoria libera.",
