  "Run the AI on your own hardware. Nothing leaves the device, nothing costs per use.": "Fai girare l'IA sul tuo hardware. Niente lascia il dispositivo, niente si paga a consumo.",
  "Runs smoothly on a 12 GB phone: expert answers, and the best at reading documents and photos.": "Fluido su un telefono da 12 GB: risposte da esperto, e il migliore a leggere documenti e foto.",
