  "Core Max, Sense, Zenith, Apex and Everest run on a computer: get them in the Attune desktop app.": "Core Max, Sense, Zenith, Apex ed Everest girano su computer: li trovi nell'app Attune per computer.",
  "Too heavy for a phone — it can close the app. Core or Blaze run smoothly here; this one is in the desktop app.": "Troppo pesante per un telefono: può far chiudere l'app. Qui Core o Blaze vanno bene; questo è nell'app per computer.",
