  "per company system, once": "per sistema aziendale, una volta",
  "Pro is bought in the Google Play version of Attune — one tap, paid by card or from your Vodafone / Orange / Etisalat balance, and it switches on by itself.": "Pro si acquista nella versione Google Play di Attune: un tocco, paghi con carta o con il credito Vodafone / Orange / Etisalat, e si attiva da solo.",
  "Cancel any time in Google Play → Subscriptions. The plan renews by itself; nothing to send, nobody to message.": "Annulla quando vuoi in Google Play → Abbonamenti. Il piano si rinnova da solo: niente da inviare, nessuno da contattare.",
