  "Nothing in your Mind matched — so this is not from your items.": "Niente nella tua Mente corrisponde, quindi questa risposta non viene dai tuoi elementi.",
  "From your past": "Dal tuo passato",
  "Nothing matches that.": "Nessun risultato corrisponde.",
  "on this day": "in questo giorno",
  "a year ago": "un anno fa",
  "from your past": "dal tuo passato",
  "Nothing to read in that.": "Non c'è niente da leggere lì.",
  "That payment did not go through, so there is nothing to record.": "Il pagamento non è andato a buon fine, quindi non c'è niente da registrare.",
  "Sent to Yusr — pick the account and confirm": "Inviato a Yusr: scegli il conto e conferma",
  "Money isn't bundled in this build.": "Soldi non è incluso in questa build.",
  "The Yusr document wasn't embedded. On the phone it loads from local assets.": "Il documento Yusr non è stato incorporato. Sul telefono si carica dai file locali.",
  "Your ledger and every zakāt ruling live here, unchanged, and free forever. Attune adds memory and plain language on top — it never calculates zakāt and never moves money on its own.": "Qui trovi il tuo registro e ogni regola della zakat, invariati e gratis per sempre. Attune aggiunge memoria e linguaggio semplice: non calcola mai la zakat e non sposta mai denaro da solo.",
  "Share a payment": "Condividi un pagamento",
  "An InstaPay confirmation, a bank SMS, a wallet receipt or a photo of one. Attune reads the amount and who it was, then opens your own transaction sheet with it filled in. You pick the account.": "Una conferma InstaPay, un SMS della banca, una ricevuta del wallet o una sua foto. Attune legge l'importo e il destinatario, poi apre la tua scheda di transazione già compilata. Il conto lo scegli tu.",
  "تم تحويل مبلغ 1,500.00 جنيه إلى AHMED MOHAMED. رقم العملية 987654321": "تم تحويل مبلغ 1,500.00 جنيه إلى AHMED MOHAMED. رقم العملية 987654321",
  "Read it": "Leggilo",
  "Reading…": "Lettura…",
  "From a photo": "Da una foto",
  "Three ways, all fine: share the SMS, WhatsApp message or screenshot to Attune from any app (it lands here by itself) · paste it above · or take/pick a photo of the receipt.": "Tre modi, tutti validi: condividi l'SMS, il messaggio WhatsApp o lo screenshot con Attune da qualsiasi app (arriva qui da solo) · incollalo sopra · oppure scatta/scegli una foto della ricevuta.",
  "read from: “": "letto da: “",
  "· account: you choose, in Yusr": "· conto: lo scegli tu, in Yusr",
  "Talk to your money": "Parla con i tuoi soldi",
  "not saved to memory": "non salvato in memoria",
  "saved to memory": "salvato in memoria",
  "Answered on this device from the figures Yusr calculated. Ask follow-ups — it keeps the thread. For zakāt it is handed the app's own numbers and forbidden from recomputing them: it explains, it does not rule.": "Risposta data su questo dispositivo con le cifre calcolate da Yusr. Fai altre domande: segue il filo. Per la zakat riceve i numeri dell'app e non può ricalcolarli: spiega, non emette giudizi.",
  "figures from Yusr's zakāt engine, not recalculated": "cifre dal motore zakat di Yusr, non ricalcolate",
  "ask a follow-up…": "fai un'altra domanda…",
  "Thinking…": "Sto pensando…",
  "What do you make of this?": "Che ne pensi?",
  "Load a model in Engine and this answers with no signal.": "Carica un modello in Motore e questo risponde anche senza segnale.",
  "What stands out": "Cosa salta all'occhio",
  "Every figure here is one Yusr calculated — the model may not produce a new number.": "Ogni cifra qui è calcolata da Yusr: il modello non può produrre numeri nuovi.",
  "What the AI is allowed to see": "Cosa può vedere l'AI",
  "Sources:": "Fonti:",
  "Added to memory": "Aggiunto alla memoria",
  "Only what you confirmed. Attune records nothing on its own.": "Solo ciò che hai confermato. Attune non registra niente da solo.",
  "No signal, so only your saved places are searchable — nothing matched.": "Senza segnale si può cercare solo tra i tuoi luoghi salvati, e nessuno corrisponde.",
  "Nothing found for that.": "Nessun risultato.",
  "Saved — it works offline now": "Salvato: ora funziona offline",
  "Map tiles cleared": "Riquadri della mappa cancellati",
  "Every area you look at is kept, so it works again with no signal. You can also download an area before you travel. Place search needs a connection; your own saved places are searchable without one.": "Ogni zona che guardi viene conservata, così funziona di nuovo anche senza segnale. Puoi anche scaricare una zona prima di partire. La ricerca dei luoghi richiede una connessione; i tuoi luoghi salvati si cercano anche senza.",
  "offline — showing saved tiles": "offline: mostro i riquadri salvati",
