  "Translated by the AI on your phone — check important names and numbers.": "Tradotto dall'AI sul tuo telefono: controlla nomi e numeri importanti.",
  "Translating needs an AI model — open Engine and install one.": "Per tradurre serve un modello AI: apri Motore e installane uno.",
  "The AI on your phone translates it piece by piece; headings, lists, tables and numbers stay in place. Long files take a few minutes.": "L'AI sul tuo telefono traduce pezzo per pezzo; titoli, elenchi, tabelle e numeri restano al loro posto. I file lunghi richiedono qualche minuto.",
