  "Long-press the box and choose Paste": "Tieni premuto il campo e scegli Incolla",
  "That isn't a link. Copy the video's link (it starts with https://) and paste it here.": "Questo non è un link. Copia il link del video (inizia con https://) e incollalo qui.",
  "{site} doesn't allow its videos to be downloaded, so Attune can't save them (Google Play removes apps that do). Links that work: direct video links, Google Drive, Dropbox, archive.org, Wikimedia Commons, and pages that show a plain video file.": "{site} non permette di scaricare i suoi video, quindi Attune non può salvarli (Google Play rimuove le app che lo fanno). Link che funzionano: link diretti a video, Google Drive, Dropbox, archive.org, Wikimedia Commons e pagine che mostrano un semplice file video.",
  "a streaming service": "un servizio di streaming",
  "this site": "questo sito",
  "That's a live-stream link (.m3u8) — it's streamed in pieces and can't be saved as one file.": "È il link di una diretta (.m3u8): viene trasmessa a pezzi e non si può salvare come un unico file.",
  "Downloading works in the Android app.": "Il download funziona nell'app Android.",
  "Google Drive didn't give the file — make sure it's shared as \"Anyone with the link\".": "Google Drive non ha fornito il file: assicurati che sia condiviso con \"Chiunque abbia il link\".",
  "This page plays a {site} video, which can't be downloaded.": "Questa pagina riproduce un video di {site}, che non si può scaricare.",
  "This page streams its video in pieces (HLS), which can't be saved as one file.": "Questa pagina trasmette il video a pezzi (HLS), che non si può salvare come un unico file.",
  "No downloadable video was found on that page.": "In quella pagina non c'è nessun video scaricabile.",
  "That link didn't give a video file (the site sent {t}).": "Quel link non ha fornito un file video (il sito ha inviato {t}).",
  "No downloadable video was found there.": "Lì non c'è nessun video scaricabile.",
  "Free includes 3 video downloads a day — Pro is unlimited": "Il piano gratuito include 3 download di video al giorno; Pro è illimitato",
