  ". Entry rules change with no notice and the cost of being wrong is a denied boarding — confirm with the embassy or the official portal before you book.": ". Le regole d'ingresso cambiano senza preavviso e un errore può costarti l'imbarco negato: verifica con l'ambasciata o il portale ufficiale prima di prenotare.",
  "When you land": "Quando atterri",
