  "install before you fly": "installale prima di partire",
  "Some of these can't be installed or signed up for once you're in the country — do it while you still have your home connection.": "Alcune non si possono installare o attivare una volta nel paese: fallo finché hai ancora la connessione di casa.",
  "SIM:": "SIM:",
  "Everything else about": "Tutto il resto su",
  "all offline": "tutto offline",
  "📶 Staying connected": "📶 Restare connessi",
  "Ask anything about being here": "Chiedi qualsiasi cosa sul posto",
  "e.g. the taxi driver won't turn the meter on, what do I say? / is this price fair for a carpet? / can I drink the tap water?": "es. il tassista non accende il tassametro, cosa gli dico? / è un prezzo giusto per un tappeto? / posso bere l'acqua del rubinetto?",
  "It knows how things actually work here — fair prices, common overcharges, what's rude. It will tell you when something needs live data it can't have offline.": "Sa come funzionano davvero le cose qui: prezzi giusti, rincari tipici, cosa è scortese. Ti dice quando una cosa richiede dati in tempo reale che offline non può avere.",
