  "Installed weights never update on their own, so a prompt that works today works the same way in a year. The fingerprint proves exactly which file is answering.": "I pesi installati non si aggiornano mai da soli, quindi un prompt che funziona oggi funziona uguale tra un anno. L'impronta dimostra esattamente quale file sta rispondendo.",
  "Add any model": "Aggiungi un modello a tua scelta",
  "unsloth/Qwen3.5-9B-GGUF:Q4_K_M   or   https://…/model.gguf": "unsloth/Qwen3.5-9B-GGUF:Q4_K_M   oppure   https://…/model.gguf",
  "Any GGUF on Hugging Face as": "Qualsiasi GGUF su Hugging Face come",
  ", or a direct https link. Specialist and fine-tuned models install the same way — the photo reader is fetched too when the repo has one.": ", oppure un link https diretto. I modelli specialistici e quelli ottimizzati si installano allo stesso modo: se il repository lo include, viene scaricato anche il lettore di foto.",
  "How it answers": "Come risponde",
  "e.g. I run a small shop in Egypt. Answer in Egyptian Arabic unless I write in English. Give prices in EGP.": "es. Ho un piccolo negozio in Egitto. Rispondi in arabo egiziano, a meno che io non scriva in inglese. Dai i prezzi in EGP.",
  "Saved when you tap outside the box. Stays on this phone.": "Salvato quando tocchi fuori dalla casella. Resta su questo telefono.",
  "Web lookup": "Ricerca sul web",
  "Only the question you look up and the pages opened leave the phone — never your conversation, files or memory.": "Escono dal telefono solo la domanda che cerchi e le pagine aperte: mai la tua conversazione, i tuoi file o la tua memoria.",
  "Hide network log": "Nascondi registro di rete",
  "made ·": "effettuate ·",
