  "Nothing has left the phone.": "Dal telefono non è uscito nulla.",
  "The model itself never uses the network. The log lists every connection the app made or refused, host and reason only — the proof behind \"nothing leaves this phone\".": "Il modello in sé non usa mai la rete. Il registro elenca ogni connessione che l'app ha fatto o rifiutato, solo host e motivo: la prova di «niente lascia questo telefono».",
