  "INT4 KV cache + sliding-window eviction, so long conversations don't grow unbounded.": "Cache KV INT4 ed eliminazione a finestra scorrevole, così le conversazioni lunghe non crescono senza limiti.",
  "Storage:": "Spazio:",
  "Compute": "Calcolo",
  "Prefill runs where compute is fastest, decode where bandwidth is. Using both raises usable bandwidth ~43 → 59 GB/s.": "Il prefill gira dove il calcolo è più veloce, la decodifica dove conta la banda. Usando entrambi la banda utile sale da ~43 a 59 GB/s.",
  "Task adapters": "Adattatori per attività",
  "Small fine-tunes for each job — this is what makes a phone-sized model punch above its weight. Loaded over the base model, a few MB each.": "Piccoli ottimizzatori per ogni compito: è ciò che fa rendere a un modello da telefono più di quanto ci si aspetti. Si caricano sopra il modello di base, pochi MB ciascuno.",
