  "Licence check": "Verifica della licenza",
  "refunds and shared keys": "rimborsi e chiavi condivise",
  "Qwen3.6 35B-A3B · long context": "Qwen3.6 35B-A3B · contesto lungo",
  "Write": "Scrivi",
  "Review": "Ripassa",
  "Long documents": "Documenti lunghi",
  "The strongest dense model that still fits a 32 GB machine. Quantisation-aware trained, so 4-bit costs almost nothing in quality here.": "Il modello denso più potente che stia ancora in un computer da 32 GB. Addestrato tenendo conto della quantizzazione, quindi a 4 bit qui la qualità cala quasi per nulla.",
  "26B-class answers with under 4B active per token. The best quality-per-second on a strong laptop.": "Risposte da classe 26B con meno di 4B attivi per token. Il miglior rapporto qualità/secondo su un portatile potente.",
  "Reads text, images and audio. Comfortable on a laptop or a 16 GB phone.": "Legge testo, immagini e audio. Va bene su un portatile o su un telefono da 16 GB.",
  "Photos": "Foto",
  "The strongest sub-10B model measured anywhere, and the best of these at reading documents and photographs.": "Il miglior modello sotto i 10B misurato ovunque, e il migliore di questi nel leggere documenti e fotografie.",
  "The one to have if your phone can hold it. Reads photographs of documents and receipts, handles Arabic and English, and a fifth bit of precision over the smaller build is a real quality difference you can feel on long answers.": "Quello da avere se il tuo telefono ce la fa. Legge fotografie di documenti e scontrini, gestisce arabo e inglese, e un quinto bit di precisione in più rispetto alla versione più piccola è una differenza di qualità reale che si sente nelle risposte lunghe.",
  "Text, images and audio on a flagship phone. Pick this over the Qwen if you want voice notes read back to you.": "Testo, immagini e audio su un telefono di fascia alta. Scegli questo al posto del Qwen se vuoi che ti rileggano i messaggi vocali.",
  "Voice": "Voce",
  "The sweet spot on an ordinary modern phone. Everything the app does, in under 3 GB.": "Il giusto compromesso su un normale telefono moderno. Tutto ciò che fa l'app, in meno di 3 GB.",
  "The same 4B model squeezed 10% smaller for a 4 GB phone. Slightly slower on older chips, and worth it to get the 4B rather than dropping to the 2B.": "Lo stesso modello 4B compresso del 10% per un telefono da 4 GB. Un po' più lento sui chip vecchi, ma conviene per avere il 4B invece di scendere al 2B.",
  "Runs on a cheap phone and still reads photographs. Short answers are good; long reasoning is where you'll notice the size.": "Gira su un telefono economico e legge comunque le fotografie. Le risposte brevi vanno bene; sui ragionamenti lunghi si nota la dimensione.",
  "For a phone that can't hold anything else. Useful for tidying and shortening text; don't ask it to reason.": "Per un telefono che non regge altro. Utile per sistemare e accorciare i testi; non chiedergli di ragionare.",
  "This device is below what any local model needs": "Questo dispositivo è sotto il minimo richiesto da qualsiasi modello locale",
  "Everything here runs on your own hardware, and the smallest useful model wants about 2 GB of memory to itself. Attune's tools that don't need a model still work.": "Tutto qui gira sul tuo hardware, e il più piccolo modello utile vuole circa 2 GB di memoria tutti per sé. Gli strumenti di Attune che non richiedono un modello funzionano comunque.",
  "Neural Engine": "Neural Engine",
  "prefill + decode": "prefill + decodifica",
  "Rewrite": "Riscrivi",
  "Field docs": "Documenti di campo",
  "It declined or dodged the question.": "Ha rifiutato o evitato la domanda.",
  "Say why you need it and what you'll do with it, and ask for the part it can answer.": "Spiega perché ti serve e cosa ne farai, e chiedi la parte a cui può rispondere.",
  "It hedged instead of committing.": "Ha tergiversato invece di sbilanciarsi.",
  "Ask it to pick one and defend it: “Choose the single best option and say why the others lose.”": "Chiedigli di sceglierne una e difenderla: «Scegli l'unica opzione migliore e spiega perché le altre perdono».",
  "That's a generic answer — it could have been written without your details.": "È una risposta generica: poteva essere scritta senza i tuoi dettagli.",
  "Give it your actual numbers and constraints, and ask it to redo the answer using only those.": "Dagli i tuoi numeri e vincoli reali e chiedigli di rifare la risposta usando solo quelli.",
  "It spent the answer restating your question.": "Ha sprecato la risposta a ripetere la tua domanda.",
  "Tell it to skip the recap and start at the answer.": "Digli di saltare il riassunto e di partire dalla risposta.",
  "It looks cut off.": "Sembra troncata.",
  "Ask it to continue from where it stopped, not to start again.": "Chiedigli di continuare da dove si è fermato, non di ricominciare.",
  "It asked you a question instead of answering.": "Ti ha fatto una domanda invece di rispondere.",
  "Answer the question inside your next prompt so it can't stall again.": "Rispondi alla domanda dentro il prossimo prompt, così non può di nuovo prendere tempo.",
  "This repeats an earlier answer — the conversation is going in circles.": "Ripete una risposta precedente: la conversazione gira in tondo.",
  "Change the angle: ask for what it would do differently, or give it a constraint it hasn't had.": "Cambia angolazione: chiedigli cosa farebbe di diverso, o dagli un vincolo che non ha ancora avuto.",
  "Sharpen": "Affina",
  "narrower and more specific — pin it down": "più stretto e più specifico: circoscrivilo",
  "Widen": "Allarga",
  "step back and ask for options you haven't considered": "fai un passo indietro e chiedi opzioni a cui non hai pensato",
  "Press": "Incalza",
  "challenge the answer and make it defend or correct itself": "metti in discussione la risposta e fagli difendere o correggere se stesso",
  "Reads clean structure well — tags mark where context ends and the task begins.": "Legge bene una struttura pulita: i tag segnano dove finisce il contesto e dove inizia il compito.",
  "Turn on Extended Thinking for hard reasoning.": "Attiva il ragionamento esteso per i ragionamenti difficili.",
  "Does best when you name the outcome and let it choose the path.": "Funziona meglio se indichi il risultato e lasci scegliere a lui il percorso.",
  "Let the router pick, or choose Thinking for complex tasks.": "Lascia scegliere al router, oppure scegli Thinking per i compiti complessi.",
  "Wants direct, concise input and defaults to short answers.": "Vuole input diretto e conciso e di base risponde in breve.",
  "Use Pro; enable Deep Research for multi-source work.": "Usa Pro; attiva Deep Research per il lavoro su più fonti.",
  "Handles direct, conversational prompts; ask for reasoning explicitly.": "Gestisce prompt diretti e colloquiali; chiedi il ragionamento in modo esplicito.",
  "Turn on Think mode for step-by-step reasoning.": "Attiva la modalità Think per il ragionamento passo passo.",
  "Strong at structured reasoning and code.": "Forte nel ragionamento strutturato e nel codice.",
  "Enable DeepThink (R1) for reasoning-heavy work.": "Attiva DeepThink (R1) per il lavoro che richiede molto ragionamento.",
  "Runs autonomously across many steps — give a goal, constraints, and a deliverable.": "Lavora in autonomia su molti passaggi: dagli un obiettivo, dei vincoli e un risultato da consegnare.",
  "Give it files/links up front; let it run async.": "Dagli subito file/link; lascialo lavorare in modo asincrono.",
  "A search engine first — told which sources to trust and to cite them.": "Prima di tutto un motore di ricerca: digli di quali fonti fidarsi e di citarle.",
  "Pick Pro or Research mode; always check the citations.": "Scegli la modalità Pro o Research; controlla sempre le citazioni.",
  "Only answers from your uploaded sources — cite passages, admit gaps.": "Risponde solo dalle fonti che hai caricato: cita i passaggi, ammetti le lacune.",
  "Upload sources first; try an Audio Overview.": "Carica prima le fonti; prova un Audio Overview.",
