  "3 templates · 5 history items": "3 modelli · 5 elementi di cronologia",
  "35B of knowledge, 3B doing the work on each token — near-frontier answers at a speed a laptop can sustain. A mixture-of-experts model keeps every expert in memory even though few run per token, so this needs the RAM of a 35B and the compute of a 3B.": "35B di conoscenza, 3B al lavoro su ogni token: risposte quasi da modello di punta a una velocità sostenibile da un portatile. Un modello a miscela di esperti tiene in memoria tutti gli esperti anche se ne lavorano pochi per token, quindi serve la RAM di un 35B e la potenza di calcolo di un 3B.",
  "A bigger length budget for reports, plans and analysis.": "Un limite di lunghezza più ampio per report, piani e analisi.",
  "Ask it as much as you like — no daily limit": "Chiedigli quanto vuoi: nessun limite giornaliero",
  "Your phone reports {n} GB of memory": "Il tuo telefono dichiara {n} GB di memoria",
  "Your computer reports {n} GB of memory": "Il tuo computer dichiara {n} GB di memoria",
  "which is comfortable for everyday use": "che va bene per l'uso di tutti i giorni",
  "which is enough, with shorter conversations": "che basta, con conversazioni più brevi",
  ", ": ", ",
  "Documents, fleet records, copilot, every domain pack": "Documenti, registri della flotta, copilota, ogni pacchetto di settore",
  "Small enough to download on mobile data if you need to.": "Abbastanza piccolo da scaricare con i dati mobili, se serve.",
  "This is a large model for a phone. It will run, and it will slow down noticeably once the phone gets warm — keep answers short, or pick the smaller one.": "È un modello grande per un telefono. Funziona, ma rallenta in modo evidente quando il telefono si scalda: tieni le risposte brevi, oppure scegli quello più piccolo.",
  "Every tool, and all 31 country packs": "Ogni strumento e tutti i 31 pacchetti paese",
  "Finds what you promised people, from your own words": "Trova ciò che hai promesso alle persone, partendo dalle tue stesse parole",
  "Fixed randomness, so a workflow gives identical output every time it runs.": "Casualità fissa, così un flusso di lavoro dà sempre lo stesso risultato a ogni esecuzione.",
  "Free web search: DuckDuckGo, Bing and Mojeek at once, then the top pages are read in full, so answers come from real passages.": "Ricerca web gratuita: DuckDuckGo, Bing e Mojeek insieme, poi le pagine migliori vengono lette per intero, così le risposte vengono da passaggi reali.",
  "Free · no key": "Gratis · senza chiave",
  "Installing… {p}%": "Installazione… {p}%",
  "It remembers everything and can search it": "Ricorda tutto e ci sa cercare dentro",
  "Learns your vocabulary and writes the way you do": "Impara il tuo vocabolario e scrive come te",
  "No account, no sign-in, nothing uploaded": "Niente account, niente accesso, niente caricato online",
  "Running": "In esecuzione",
  "Loading the model…": "Caricamento del modello…",
  "Nothing in the app can reach the internet — no web lookup, no maps, no downloads. The model and everything on the phone keep working.": "Nulla nell'app può raggiungere internet: niente ricerca web, mappe o download. Il modello e tutto ciò che è sul telefono continuano a funzionare.",
  "The model reasons first on every question. Clearly better on hard problems, but on a phone the answer starts 30–90 s later. Off: tap “Think” on just the questions that need it.": "Il modello ragiona prima su ogni domanda. Decisamente meglio sui problemi difficili, ma su un telefono la risposta parte 30–90 s dopo. Se è disattivato: tocca «Pensa» solo sulle domande che ne hanno bisogno.",
  "The same model as below, given the memory to hold a whole book of context at once. On a 48 GB machine the spare RAM is better spent on context than on precision — you can hand it an entire contract or a year of notes and it keeps all of it in view.": "Lo stesso modello qui sotto, con la memoria per tenere un intero libro di contesto in una volta. Su una macchina da 48 GB la RAM in più rende meglio sul contesto che sulla precisione: puoi dargli un contratto intero o un anno di note e tiene tutto sott'occhio.",
  "The whole assistant, on your device": "L'intero assistente, sul tuo dispositivo",
  "Works entirely offline. No account, ever.": "Funziona del tutto offline. Mai un account.",
  "Your API key": "La tua chiave API",
