  "Notifications are off for Attune — tap to allow them, or reminders can't appear.": "Le notifiche sono disattivate per Attune: tocca per consentirle, altrimenti i promemoria non possono comparire.",
  "Reminders may come up to 10 minutes late. Tap to allow “Alarms & reminders” for Attune so they ring on the minute.": "I promemoria possono arrivare con fino a 10 minuti di ritardo. Tocca per consentire «Sveglie e promemoria» ad Attune, così suonano al minuto esatto.",
  "In the browser reminders are only listed — the Android app rings them.": "Nel browser i promemoria vengono solo elencati: li fa suonare l'app Android.",
  "from a promise": "da una promessa",
  "Reminder": "Promemoria",
