  "Put the ask after the data (Gemini/GPT guidance)": "Metti la richiesta dopo i dati (indicazione Gemini/GPT)",
  "Define the output shape explicitly": "Definisci con precisione la forma del risultato",
  "Name the goal so the model reasons toward it": "Indica l'obiettivo perché il modello ragioni verso di esso",
  "Specificity → fewer misinterpretations": "Più specificità → meno fraintendimenti",
  "Goal-framing beats tone adjectives alone": "Indicare l'obiettivo vale più dei soli aggettivi di tono",
  "Data first, question last improves grounding": "Prima i dati, la domanda per ultima: migliora l'aderenza ai fatti",
  "Role-free outcome framing (2026 guidance)": "Impostazione per risultato senza ruolo (indicazione 2026)",
  "Explicit output shape reduces rework": "Una forma del risultato esplicita riduce il rifacimento",
  "Goal + constraint framing produces usable scripts": "Obiettivo + vincolo producono copioni utilizzabili",
  "Stated criteria prevent generic pro/con lists": "Criteri dichiarati evitano elenchi generici di pro e contro",
  "Concrete constraints beat generic advice": "I vincoli concreti battono i consigli generici",
  "Time constraints force actionable plans": "I vincoli di tempo costringono a piani attuabili",
  "Matching to the posting outperforms templates": "Adattarsi all'annuncio funziona meglio dei modelli standard",
  "Role-specific prompting beats generic question lists": "Prompt specifici per il ruolo battono gli elenchi generici di domande",
  "Source-anchored prompts reduce invented detail": "Prompt ancorati alle fonti riducono i dettagli inventati",
  "Constraints up front prevent generic travel advice": "I vincoli all'inizio evitano consigli di viaggio generici",
  "Explaining the 'why' improves targeting (Anthropic)": "Spiegare il «perché» migliora la mira (Anthropic)",
  "Search tools need source + recency constraints": "Gli strumenti di ricerca richiedono vincoli su fonte e attualità",
  "Constraints up front prevent generic answers": "I vincoli all'inizio evitano risposte generiche",
  "Active recall outperforms re-reading": "Il richiamo attivo batte la rilettura",
  "Sectioned output aids comprehension": "Un risultato in sezioni facilita la comprensione",
  "Explicit critique requests beat 'what do you think'": "Chiedere esplicitamente una critica batte «cosa ne pensi»",
  "Naming review axes prevents shallow feedback": "Indicare gli assi della revisione evita feedback superficiali",
  "Include context + attempted fixes for accuracy": "Includi contesto e correzioni già provate per essere più preciso",
  "Section-by-section output beats 'write a page'": "Un risultato sezione per sezione batte «scrivi una pagina»",
  "Persona-specific prompts improve targeting": "Prompt specifici per il personaggio migliorano la mira",
  "Stating criteria prevents generic pro/con lists": "Dichiarare i criteri evita elenchi generici di pro e contro",
  "Level-setting improves explanation fit": "Definire il livello rende la spiegazione più adatta",
  "Specifying length prevents rambling summaries": "Indicare la lunghezza evita riassunti prolissi",
  "Ask to implement, not 'suggest changes' (Anthropic)": "Chiedi di implementare, non di «suggerire modifiche» (Anthropic)",
  "Reasoning models excel with clear scope, no examples": "I modelli di ragionamento rendono con ambito chiaro, senza esempi",
  "Name every state so nothing is left ambiguous": "Nomina ogni stato così non resta nulla di ambiguo",
  "Natural language + explicit variety works on GPT": "Linguaggio naturale + varietà esplicita funziona su GPT",
  "Outcome framing beats feature lists": "Impostare per risultato batte gli elenchi di funzioni",
  "Gemini prefers direct, constrained prompts": "Gemini preferisce prompt diretti e vincolati",
  "Short + specific tone yields natural output": "Tono breve e specifico dà un risultato naturale",
  "Chain-of-thought: +~40% avg on hard reasoning (Wei et al.); MultiArith 18%→79%. Skip on reasoning models — minimal gain, more latency.": "Catena di pensiero: +~40% in media sul ragionamento difficile (Wei et al.); MultiArith dal 18% al 79%. Da saltare sui modelli di ragionamento: guadagno minimo, più latenza.",
  "1–5 examples (few-shot) raise pattern-task accuracy up to +43%; best on non-reasoning models like Gemini. Don't add examples for pure reasoning tasks — can hurt.": "1–5 esempi (few-shot) alzano la precisione sui compiti di schemi fino a +43%; ideali sui modelli non di ragionamento come Gemini. Non aggiungere esempi per compiti di puro ragionamento: possono danneggiare.",
  "OpenAI/Anthropic 2026: describe what a good result looks like; over-instructing adds noise on modern models.": "OpenAI/Anthropic 2026: descrivi che aspetto ha un buon risultato; troppe istruzioni aggiungono rumore sui modelli moderni.",
  "2026 practice: set how hard to think (thinking/effort control) and spend words on the outcome, not on 'think step by step'.": "Pratica 2026: imposta quanto deve pensare (controllo di thinking/effort) e spendi le parole sul risultato, non su «pensa passo passo».",
  "Clarification-first reduces wasted turns — the model gathers missing context instead of guessing.": "Chiarire prima riduce i giri sprecati: il modello raccoglie il contesto mancante invece di tirare a indovinare.",
  "Outcome criteria (what 'good' means) outperform process instructions on 2026 models.": "I criteri di risultato (cosa significa «buono») battono le istruzioni di processo sui modelli del 2026.",
  "Verification steps reduce errors on factual/analytical tasks.": "I passaggi di verifica riducono gli errori nei compiti fattuali e analitici.",
  "Explicit sections prevent rambling updates": "Sezioni esplicite evitano aggiornamenti prolissi",
  "Asking for risks surfaces what you forgot": "Chiedere i rischi fa emergere ciò che avevi dimenticato",
  "Outcome framing keeps feedback constructive": "Impostare per risultato mantiene il feedback costruttivo",
  "Explicit audience prevents vague procedures": "Un pubblico esplicito evita procedure vaghe",
  "Spaced repetition beats massed practice": "La ripetizione distanziata batte lo studio concentrato",
  "Worked examples aid transfer to new problems": "Gli esempi svolti aiutano a trasferire su problemi nuovi",
  "Planning prompts reduce rework on complex tasks": "I prompt di pianificazione riducono il rifacimento sui compiti complessi",
  "Explicitly requesting edge cases improves coverage": "Chiedere esplicitamente i casi limite migliora la copertura",
  "Specificity outperforms enthusiasm in cold outreach": "La specificità batte l'entusiasmo nei contatti a freddo",
  "Goal-anchored planning beats idea dumps": "Pianificare ancorati all'obiettivo batte gli sfoghi di idee",
  "Requesting alternatives counters fixation": "Chiedere alternative contrasta la fissazione",
  "Citation requirements reduce unsupported claims": "Richiedere le citazioni riduce le affermazioni senza fondamento",
  "Grounding in supplied sources reduces hallucination; tell it to admit gaps.": "Basarsi sulle fonti fornite riduce le allucinazioni; digli di ammettere le lacune.",
  "Searching the web for facts and figures…": "Ricerca sul web di fatti e cifre…",
