  "When a column in one table names records of another (a job's customer, an invoice's crane), the phone finds it here and links them — no relationships to draw by hand.": "Quando una colonna di una tabella nomina record di un'altra (il cliente di un lavoro, la gru di una fattura), il telefono lo trova qui e li collega: niente relazioni da disegnare a mano.",
