  "not read: {f}": "non letto: {f}",
  "From the phone's Notebook app: open a note (or select several) → Share → Attune → “Save to Shelf”. Or pick exported files here: text, Word, PDF, web pages, Google Keep, Evernote, a .zip, or photos of notes.": "Dall'app Note del telefono: apri una nota (o selezionane più d'una) → Condividi → Attune → «Salva nello Scaffale». Oppure scegli qui i file esportati: testo, Word, PDF, pagine web, Google Keep, Evernote, uno .zip o foto di note.",
  "Versions & prices": "Versioni e prezzi",
  "Pros & cons": "Pro e contro",
  "Compare with rivals": "Confronta con i concorrenti",
  "Latest news": "Ultime notizie",
  "Those results were off-topic — searching another way…": "Quei risultati erano fuori tema: cerco in un altro modo…",
  "Nothing found for that — try the area's name too (e.g. “… New Cairo”), or move the map there and search again.": "Non ho trovato niente: prova anche con il nome della zona (es. «… Nuovo Cairo»), oppure sposta la mappa lì e cerca di nuovo.",
  "from the map's centre": "dal centro della mappa",
  "saved place": "luogo salvato",
  "Save this place": "Salva questo luogo",
  "This phone can't share its location with the app.": "Questo telefono non può condividere la sua posizione con l'app.",
  "Location is off for Attune — allow it in the phone's settings to see where you are.": "La posizione è disattivata per Attune: consentila nelle impostazioni del telefono per vedere dove sei.",
  "Couldn't get your location — check that location is on.": "Impossibile ottenere la tua posizione: controlla che sia attiva.",
  "“{n}” isn't kept on this phone any more — pick the file again.": "«{n}» non è più conservato su questo telefono: scegli di nuovo il file.",
  "tap to continue": "tocca per continuare",
  "The text and your questions are kept on this phone only. Forget removes them.": "Il testo e le tue domande restano solo su questo telefono. Dimentica li rimuove.",
  "Web · Auto": "Web · Auto",
  "Web: Auto — it searches only when a question needs fresh facts": "Web: Auto: cerca solo quando una domanda richiede fatti aggiornati",
  "Pick the best model for each question": "Scegli il modello migliore per ogni domanda",
  "Reading your {f} conversation…": "Lettura della tua conversazione {f}…",
  "Reading the conversation…": "Lettura della conversazione…",
  "Shared links are opened in the Android app — or paste the conversation's text here.": "I link condivisi si aprono nell'app Android, oppure incolla qui il testo della conversazione.",
  "I read your conversation with {f}{t} (about {n} words). Ask me anything about it — check it, summarise it, or carry on from where it stopped.": "Ho letto la tua conversazione con {f}{t} (circa {n} parole). Chiedimi qualsiasi cosa: controllala, riassumila o continua da dove si è fermata.",
  "Attune · the AI runs on your device · no account, no sign-in · web lookup only when a question needs it (Auto) — switch it off with the Web button": "Attune · l'IA gira sul tuo dispositivo · niente account, niente accesso · ricerca web solo quando una domanda lo richiede (Auto): disattivala con il pulsante Web",
  "Web: Off — nothing is looked up": "Web: Off — non si cerca nulla",
  "While Web is off in Chat, questions about prices, specs, news, scores or this year are still looked up (only the search words leave the phone). Off: nothing is looked up unless you turn Web on.": "Con Web spento in Chat, le domande su prezzi, specifiche, notizie, punteggi o quest'anno vengono comunque cercate (lascia il telefono solo il testo della ricerca). Off: non si cerca nulla finché non attivi Web.",
  "The model wrote nonsense — restarting it in safe mode and asking again…": "Il modello ha scritto assurdità: lo riavvio in modalità sicura e richiedo…",
  "This model writes nonsense on this phone, even in safe mode. Pick another model in Engine (Core works well) and tell us which one failed.": "Questo modello scrive assurdità su questo telefono, anche in modalità sicura. Scegli un altro modello in Motore (Core funziona bene) e dicci quale ha fallito.",
  "Safe mode is on for this model: it once wrote nonsense on this phone, so it runs without speed tricks and with full-precision memory (a little slower, same answers).": "La modalità sicura è attiva per questo modello: una volta ha scritto assurdità su questo telefono, quindi gira senza trucchi di velocità e con memoria a piena precisione (un po' più lento, stesse risposte).",
  "Turn safe mode off": "Disattiva la modalità sicura",
  "Or any topic you like": "Oppure qualsiasi argomento vuoi",
